## Why This Is Asked
Tests ability to formulate DP with non-trivial constraints (non-adjacent picks), carefully handle feasibility, and compare memoization vs bottom-up tabulation and space optimization.

## Key Concepts
- DP state (i, t) representing position and how many selections left
- Transitions: skip i (i+1,t) and take i (a[i] + f(i+2,t-1))
- Base conditions
- Impossibility when m > ceil(n/2)
- Space optimization via rolling arrays

## Code Example
```javascript
function maxSumNonAdjacent(a, m) {
  const n = a.length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n+3 }, () => Array(m+1).fill(NEG));
  for (let i=0; i<=n; i++) dp[i][0] = 0;
  for (let i=n-1; i>=0; i--) {
    for (let t=1; t<=m; t++) {
      const skip = dp[i+1][t];
      const take = a[i] + dp[i+2][t-1];
      dp[i][t] = Math.max(skip, take);
    }
  }
  return dp[0][m];
}
```

## Follow-up Questions
- How to reconstruct the chosen indices?
- How to extend to at-most-m or negative values handling?
- How would you optimize to O(m) space with path reconstruction?

## Why This Is Asked

This question adds counting of optimal partitions to a standard min-max DP, testing both correctness and edge-case handling in a realistic workload-balancing scenario.

## Key Concepts

- DP with a value-cost pair (minCost, count) and prefix sums for O(1) subarray sums
- Top-down memoization and bottom-up tabulation with identical transitions
- Edge-case handling: n<k invalid, zeros, large sums

## Code Example

```javascript
function minCostPartitions(nums, k){
  const n = nums.length;
  const pref = new Array(n+1).fill(0);
  for(let i=0;i<n;i++) pref[i+1]=pref[i]+nums[i];
  const dp = Array.from({length:n+1},()=>Array.from({length:k+1},()=>null));
  for(let i=1;i<=n;i++) dp[i][1] = {best: pref[i], count:1};
  for(let i=1;i<=n;i++){
    for(let j=2;j<=Math.min(i,k);j++){
      let best = Infinity, cnt = 0;
      for(let t=j-1;t<=i-1;t++){
        const last = pref[i]-pref[t];
        const prev = dp[t][j-1];
        if(!prev) continue;
        const cand = Math.max(prev.best, last);
        if(cand < best){ best = cand; cnt = prev.count; }
        else if(cand === best){ cnt += prev.count; }
      }
      dp[i][j] = {best, count: cnt};
    }
  }
  const res = dp[n][k];
  return res ? {cost: res.best, ways: res.count} : null;
}
```

## Follow-up Questions

- How would you modify to return all partition indices achieving the min cost?
- Could you optimize to O(nk) time with a narrowed search if nums are non-decreasing?

## Why This Is Asked

Tests practical algorithm design that blends classic sorts and data-structure choices. It assesses the ability to identify run structures, select appropriate sorting strategies by run size, and implement an efficient, stable k-way merge.

## Key Concepts

- Natural monotone runs detection in O(n)
- Insertion sort for small ranges; mergesort for larger ranges
- K-way merge with a min-heap and lazy advancement
- Stability guarantees and complexity trade-offs

## Code Example

```javascript
function hybridSort(a){
  const n=a.length; 
  // 1) detect monotone runs
  const runs=[]; let i=0;
  while(i<n){
    let j=i+1;
    while(j<n && a[j-1] <= a[j]) j++;
    runs.push([i,j]);
    i=j;
  }
  // 2) sort each run
  for(const [l,r] of runs){
    if(r-l <= 32) insertionSort(a,l,r);
    else mergeSort(a,l,r);
  }
  // 3) k-way merge using a min-heap
  const heap=new MinHeap((x,y)=> x.val<y.val);
  for(let idx=0; idx<runs.length; idx++){
    const [l,r]=runs[idx];
    if(l<r) heap.push({val:a[l], pos:l, runIdx:idx});
  }
  const out=new Array(n); let k=0;
  while(!heap.isEmpty()){
    const {val,pos,runIdx}=heap.pop();
    out[k++]=val;
    const [l,r]=runs[runIdx];
    const next=pos+1;
    if(next<r) heap.push({val:a[next], pos:next, runIdx});
  }
  for(let t=0;t<n;t++) a[t]=out[t];
}

function insertionSort(a,l,r){
  for(let i=l+1;i<r;i++){
    const key=a[i]; let j=i-1;
    while(j>=l && a[j]>key){ a[j+1]=a[j]; j--; }
    a[j+1]=key;
  }
}

function mergeSort(a,l,r){
  if(r-l<=1) return;
  const m=(l+r)>>1;
  mergeSort(a,l,m); mergeSort(a,m,r);
  // merge [l,m) and [m,r)
  const left=a.slice(l,m); let i=0, j=m, t=l;
  while(i<left.length && j<r) a[t++]= left[i++]<a[j]? left[i-1]: a[j++];
  while(i<left.length) a[t++]=left[i++];
  while(j<r) a[t++]=a[j++];
}

class MinHeap{
  constructor(cmp){ this.a=[]; this.cmp=cmp||((x,y)=> x<y); }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  pop(){ if(this.a.length===0) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.sinkDown(0); } return top; }
  isEmpty(){ return this.a.length===0; }
  bubbleUp(n){ const a=this.a[n]; while(n>0){ const p=(n-1)>>1; if(this.cmp(a, this.a[p])){ this.a[n]=this.a[p]; n=p; } else break; } this.a[n]=a; }
  sinkDown(n){ const length=this.a.length; const element=this.a[n]; while(true){ let child2=(n+1)*2, child1=child2-1; let swap=null; if(child1<length){ if(this.cmp(this.a[child1], element)) swap=child1; } if(child2<length){ if(this.cmp(this.a[child2], swap===null?element:this.a[child1])) swap=child2; } if(swap===null) break; this.a[n]=this.a[swap]; n=swap; } this.a[n]=element; }
}
```

## Follow-up Questions

- How would you adapt for external sorting with limited memory?
- How does this approach behave with highly repetitive data, and can you optimize further?

## Why This Is Asked
Demonstrates combined data structures and time-based eviction. Tests ability to design per-key streaming aggregates with real-time top-K, using arrays/linked lists/hashtable/heap and lazy deletions.

## Key Concepts
- Sliding window aggregation; - Hash maps for per-tag buckets; - Deques for per-tag event queues; - Max-heap with lazy invalidation for top-K.

## Code Example
```javascript
class SlidingTagTopK {
  constructor(windowMs){ this.W=windowMs; this.tagMap=new Map(); this.heap=[]; this.ver=0; }
  _expire(tag, now){ const b=this.tagMap.get(tag); while (b.queue.length && b.queue[0].ts <= now - this.W){ b.sum -= b.queue.shift().val; } }
  addEvent(tag, userId, value, ts){ let b=this.tagMap.get(tag); if(!b){ b={sum:0, queue:[], ver:0}; this.tagMap.set(tag,b);} this._expire(tag, ts); b.queue.push({ts, val: value}); b.sum += value; this.ver++; // push new entry
    this._heapPush({sum: b.sum, tag, ver:this.ver}); }
  topK(K){ // lazy
    const res=[]; const seen=new Set(); while (res.length<K && this.heap.length){ const top=this._heapPop(); if (top.ver===this.tagMap.get(top.tag).ver){ res.push(top.tag); seen.add(top.tag); } }
    return res;
  }
}
```

