## Why This Is Asked

This problem tests advanced dynamic programming: partitioning with a non-trivial segment cost that depends on min and max, requiring careful state design and in-loop maintenance of subproblem results. It also validates producing both memoized and iterative solutions and analyzing time/space trade-offs.

## Key Concepts

- DP with partition states
- In-loop maintenance of running min and max
- Top-down memoization vs bottom-up tabulation
- Time complexity: O(D*N^2); Space: O(D*N)

## Code Example

```javascript
// Top-down memoized
function minCost(A, D){
  const N = A.length;
  const memo = Array.from({length:D+1}, ()=> Array(N).fill(null));
  function solve(d, i){
    if (d === 1){
      let mn = Infinity, mx = -Infinity;
      for (let k = 0; k <= i; k++){ mn = Math.min(mn, A[k]); mx = Math.max(mx, A[k]); }
      return mn * mx;
    }
    if (memo[d][i] != null) return memo[d][i];
    let mn = Infinity, mx = -Infinity; let best = Infinity;
    for (let j = i; j >= d-1; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      best = Math.min(best, solve(d-1, j-1) + mn*mx);
    }
    memo[d][i] = best; return best;
  }
  return solve(D, N-1);
}

// Bottom-up
function minCostBottom(A, D){
  const N = A.length, INF = 1e18;
  const dp = Array.from({length:D+1}, ()=> Array(N).fill(INF));
  // base: d = 1
  for (let i = 0; i < N; i++){
    let mn = A[i], mx = A[i];
    for (let j = i; j >= 0; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      if (j === 0) dp[1][i] = Math.min(dp[1][i], mn*mx);
    }
  }
  for (let d = 2; d <= D; d++){
    for (let i = d-1; i < N; i++){
      let mn = A[i], mx = A[i];
      for (let j = i; j >= d-1; j--){
        mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
        dp[d][i] = Math.min(dp[d][i], dp[d-1][j-1] + mn*mx);
      }
    }
  }
  return dp[D][N-1];
}
```

## Why This Is Asked
Tests ability to frame a sign-assignment problem as a DP and implement both memoization and tabulation, a common interview pattern.

## Key Concepts
- DP state reduction to subset sum
- Space optimization with a 1D array
- Memoization vs bottom-up trade-offs

## Code Example
```javascript
// Tabulation and Memo versions
function countTargetSumTab(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const dp = Array(target+1).fill(0);
  dp[0] = 1;
  for (const n of nums) {
    for (let t = target; t >= n; t--) dp[t] += dp[t-n];
  }
  return dp[target];
}

function countTargetSumMemo(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const memo = new Map();
  function dfs(i, sum){
    if (sum > target) return 0;
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i+':'+sum;
    if (memo.has(key)) return memo.get(key);
    const res = dfs(i+1, sum+nums[i]) + dfs(i+1, sum);
    memo.set(key, res);
    return res;
  }
  return dfs(0,0);
}
```

